from typing import List

class Solution:
    def singleNumber(self, nums: List[int]) -> int:
        result = 0
        for i in range(32):
            bit_sum = 0
            for x in nums:
                bit_sum += (x >> i) & 1
            if bit_sum % 3:
                result |= 1 << i
        # Convert from unsigned 32-bit to signed Python integer.
        return result if result <= 0x7FFFFFFF else result - 0x100000000

