from typing import List

class Solution:
    def singleNumber(self, nums: List[int]) -> int:
        ones = 0
        twos = 0
        for x in nums:
            # Move bits through states: unseen -> ones -> twos -> unseen.
            ones = (ones ^ x) & ~twos
            twos = (twos ^ x) & ~ones
        return ones

